), clean AS (
 SELECT DISTINCT ON (university_id,lower(regexp_replace(name,'[^a-zA-Z0-9]','','g'))) *
 FROM incoming
 ORDER BY university_id,lower(regexp_replace(name,'[^a-zA-Z0-9]','','g'))
)
INSERT INTO public.programmes
(university_id,name,slug,field,qualification,degree_type,duration,programme_url,source_url,
 primary_source_url,source_urls,source_tier,verification_status,verified,needs_review,
 verification_method,verification_notes,notes,field_sources)
SELECT c.university_id,c.name,c.slug,c.field,c.qualification,c.degree_type,c.duration,c.source_url,c.source_url,
 c.source_url,ARRAY[c.source_url],'official_institution_catalogue','source_linked_needs_individual_review',
 false,true,'Official institution programme list',
 'Programme title and award label copied from the institution official programme list. Current admission availability and detail require individual review.',
 'Official-source linked; not verified.',jsonb_build_object('name',c.source_url,'qualification',c.source_url,'duration',c.source_url,'institution',c.source_url)
FROM clean c
WHERE NOT EXISTS (
 SELECT 1 FROM public.programmes p
 WHERE p.university_id=c.university_id
 AND lower(regexp_replace(p.name,'[^a-zA-Z0-9]','','g'))=lower(regexp_replace(c.name,'[^a-zA-Z0-9]','','g'))
)
ON CONFLICT DO NOTHING;
